promos.after:
r => {
          if (r.status === 'Effected' && !r.applied) {
            const e = empById(r.emp); if (e) { e.designation = r.propDes || e.designation; if (r.propGrade) e.grade = r.propGrade; e._u = nowISO(); (e._h = e._h || []).push({ t: e._u, by: USER.email, s: `Promoted to ${r.propDes} (${r.id})` }) }
            if (r.curCtc && r.propCtc) addRec('increments', { emp: r.emp, eff: r.eff, itype: 'Promotion', prev: r.curCtc, next: r.propCtc, approver: myEmp(), letter: 'No', status: 'Approved' });
            addRec('actions', { title: `Issue promotion letter to ${empText(r.emp)}`, cat: 'Promotion', emp: r.emp, src: `Promotion ${r.id}`, pri: 'High', due: addDays(tdy(), 3), remind: '1 day before', repeat: 'None', status: 'Open' }); r.applied = true; toast('Master data and Increment history updated; promotion-letter action created.')
          }
        }
